// titanarb-benchmark runs one deterministic, read-only three-quote workload.
package main
import("context";"encoding/json";"fmt";"math/big";"os";"runtime";"time";"golang.org/x/sys/windows";"github.com/titanarb/titanarb-go/internal/config";"github.com/titanarb/titanarb-go/internal/metrics";"github.com/titanarb/titanarb-go/internal/pools";"github.com/titanarb/titanarb-go/internal/quotes";"github.com/titanarb/titanarb-go/internal/rpc")
type result struct{Runtime string `json:"runtime"`; Block uint64 `json:"block"`; Route string `json:"route"`; RouteLimit int `json:"route_limit"`; QuoteCount int `json:"quote_count"`; PoolDiscoveryS float64 `json:"pool_discovery_s"`; QuoteS float64 `json:"quote_s"`; RouteEvaluationS float64 `json:"route_evaluation_s"`; TotalCycleS float64 `json:"total_cycle_s"`; RPCCalls uint64 `json:"rpc_calls"`; CacheHits uint64 `json:"cache_hits"`; MemoryPeakBytes uint64 `json:"memory_peak_bytes"`; CPUProcessS float64 `json:"cpu_process_s"`; AmountOut string `json:"amount_out"`}
func cpuTime()float64{var c,e,k,u windows.Filetime;if windows.GetProcessTimes(windows.CurrentProcess(),&c,&e,&k,&u)!=nil{return 0};return float64((uint64(k.HighDateTime)<<32|uint64(k.LowDateTime))+(uint64(u.HighDateTime)<<32|uint64(u.LowDateTime)))/1e7}
func main(){cpuStart:=cpuTime();ctx:=context.Background(); cfg,err:=config.LoadMarketConfig(os.Getenv("BENCH_CONFIG"));if err!=nil{panic(err)};m:=metrics.New();client:=rpc.New(os.Getenv("BENCH_RPC_URL"),15*time.Second,0,m); symbols:=[]string{"USDC","WETH","ARB","USDC"};d:=pools.NewDiscoverer(client,cfg.UniswapFactory,cfg.CamelotFactory,cfg.UniswapFeeTiers);start:=time.Now(); discovery:=time.Now(); hops:=make([]pools.Pool,0,3);for i:=0;i<3;i++{a,b:=cfg.Tokens[symbols[i]],cfg.Tokens[symbols[i+1]];found,e:=d.DiscoverPair(ctx,a.Address,b.Address);if e!=nil{panic(e)};var chosen *pools.Pool;for j:=range found{if found[j].DEX==pools.UniswapV3&&(chosen==nil||found[j].Liquidity.Cmp(chosen.Liquidity)>0){chosen=&found[j]}};if chosen==nil{panic("expected Uniswap pool")};hops=append(hops,*chosen)};discoveryDur:=time.Since(discovery);uni:=quotes.NewUniswapV3(client,cfg.UniswapQuoterV2,m);qstart:=time.Now();amount:=big.NewInt(1_000_000_000);for i,p:=range hops{q,e:=uni.Quote(ctx,quotes.Request{TokenIn:cfg.Tokens[symbols[i]].Address,TokenOut:cfg.Tokens[symbols[i+1]].Address,AmountIn:amount,Pool:p});if e!=nil{panic(e)};amount=q.AmountOut};quoteDur:=time.Since(qstart);block,_:=client.BlockNumber(ctx);var mem runtime.MemStats;runtime.ReadMemStats(&mem);s:=m.Snapshot();json.NewEncoder(os.Stdout).Encode(result{"go",block,"USDC -> WETH -> ARB -> USDC",1,3,discoveryDur.Seconds(),quoteDur.Seconds(),quoteDur.Seconds(),time.Since(start).Seconds(),s.RPCCalls,s.CacheHits,mem.TotalAlloc,cpuTime()-cpuStart,amount.String()});fmt.Fprint(os.Stderr,"")}
